"""Persistent, readable source identities in the files and sales workspaces."""
HTML='''<section id="so-source-identity" class="source-identity" role="status" aria-live="polite"><h3>DATOS QUE CONSULTA ESTA PROPUESTA</h3><div id="so-source-current"></div><button id="so-source-files" type="button">Revisar o cambiar el expediente activo</button><div id="so-source-evaluated"></div></section>'''
JS=r'''
function sourceIdentityFields(host,source){const list=document.createElement('dl');list.className='source-identity-fields';[['Empresa',(source.legal_name||source.company_name||source.company_id)+' · '+source.company_id],['Archivo / versión indicada en el nombre',source.filename||'Expediente documental base · no hay un Excel exclusivo seleccionado'],['Fecha de corte',stockDate(source.as_of_date||source.documentary_cutoff)],['Identificador de versión',(source.dataset_id||source.version_id||'').slice(0,12)]].forEach(([name,value])=>{const box=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;box.append(dt,dd);list.append(box)});host.append(list)}
function resetSourceIdentity(){const box=$('so-source-current');if(box){box.replaceChildren();box.textContent='Actualizando la empresa y su versión…';$('so-source-identity').dataset.status='LOADING';$('so-source-evaluated').replaceChildren()}if($('received-source-current'))$('received-source-current').textContent='Actualizando la versión consultada…'}
function renderSourceIdentity(){const source=state?.source_status,box=$('so-source-current');if(!box)return;box.replaceChildren();if(!source||source.dataset_id!==$('dataset').value){resetSourceIdentity();return}$('so-source-identity').dataset.status=source.status;const badge=document.createElement('strong');badge.className='source-usage';badge.dataset.status=source.status;badge.textContent=({ACTIVE:'ACTIVO · EN USO',HISTORICAL:'HISTÓRICO · SOLO CONSULTA',UNACTIVATED:'CARGADO · SIN ACTIVAR',BASELINE:'EXPEDIENTE BASE · SIN EXCEL EXCLUSIVO'})[source.status];const note=document.createElement('p');note.textContent=source.message;box.append(badge);sourceIdentityFields(box,source);box.append(note);const received=$('received-source-current');if(received){received.replaceChildren();const title=document.createElement('strong');title.textContent='EXPEDIENTE UTILIZADO PARA PROPUESTAS · '+badge.textContent;received.append(title);sourceIdentityFields(received,source)}}
function renderEvaluatedSource(result){const host=$('so-source-evaluated');if(!host)return;host.replaceChildren();if(!result)return;const ctx=result.documentary_context;if(!ctx)return;const title=document.createElement('strong');title.textContent='ÚLTIMA EVALUACIÓN · DATOS UTILIZADOS';const note=document.createElement('p');note.textContent='Evaluación de estas condiciones conservada con la versión y referencia documental indicadas.';host.append(title);sourceIdentityFields(host,{...ctx,filename:ctx.exclusive_workbook?.filename,as_of_date:ctx.documentary_cutoff});host.append(note)}
function appendReceivedUsage(row,batch){const cell=document.createElement('td');cell.className='received-usage';const badge=document.createElement('strong');badge.className='source-usage';const active=batch.workbook_usage==='ACTIVE';badge.dataset.status=active?'ACTIVE':'RECEIVED';badge.textContent=active?'ACTIVO · EN USO':'RECIBIDO · SIN ACTIVAR COMO EXPEDIENTE';cell.append(badge);for(const current of batch.active_workbooks||[]){const note=document.createElement('p');note.textContent='Versión '+current.dataset_id.slice(0,12)+' · '+stockDate(current.as_of_date);cell.append(note)}row.insertBefore(cell,row.children[3]);row.dataset.usage=active?'ACTIVE':'RECEIVED'}
$('so-source-files').onclick=()=>{view('archivos');$('exclusive-workbook-panel').scrollIntoView({behavior:'smooth',block:'start'})};
'''
CSS='''.source-identity{border:2px solid #548c80;border-top-width:6px;background:#edf7f3;padding:20px;border-radius:10px;margin:0 0 24px;scroll-margin-top:20px}.source-identity h3{margin:0 0 16px;font-size:18px;color:#174b43}.source-identity[data-status=HISTORICAL],.source-identity[data-status=UNACTIVATED],.source-identity[data-status=BASELINE]{background:#fff7e8;border-color:#b88a37}.source-identity[data-status=LOADING]{background:#eef2f6;border-color:#8a9aaa}.source-identity-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:16px 0}.source-identity-fields dt{font-size:13px;color:#506378;font-weight:600}.source-identity-fields dd{margin:5px 0 0;font-size:16px;font-weight:700;overflow-wrap:anywhere;color:#193a57}.source-usage{display:inline-block;padding:7px 10px;border:1px solid #81ae9b;border-radius:6px;background:#dcefe4;color:#225547;font-size:12px;line-height:1.5}.source-usage[data-status=HISTORICAL],.source-usage[data-status=UNACTIVATED],.source-usage[data-status=BASELINE]{background:#fff0cd;border-color:#bd9b56;color:#725518}.source-usage[data-status=RECEIVED]{background:#eef1f5;border-color:#c0cad5;color:#42566b}.received-usage{min-width:170px;white-space:normal!important}.received-usage p{font-size:12px;line-height:1.5}#so-source-evaluated:not(:empty){border-top:1px solid #a8c3b9;padding-top:18px;margin-top:18px}#received-source-current{padding:18px;background:#edf4fb;border:1px solid #b8cee5;border-radius:9px;margin:16px 0}@media(max-width:650px){.source-identity-fields{grid-template-columns:minmax(0,1fr)}}'''
